-- ============================================================================
-- OT Consulting - almacen dimensional (Etapa 5) para MySQL 8.0 o superior
-- Genera la base de datos 'otc_dw' con 12 tablas del modelo y la tabla PARAMETROS.
-- Uso:  mysql -u root -p < 01_esquema_y_datos.sql      (o abrirlo en MySQL Workbench y ejecutarlo)
-- Datos con corte al 17 de noviembre de 2026.
-- Las columnas de texto usan utf8mb4_bin (distingue mayusculas y acentos), igual que el almacen original.
-- ============================================================================
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS otc_dw DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
USE otc_dw;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS PARAMETROS;
DROP TABLE IF EXISTS HECHOS_HABILIDAD;
DROP TABLE IF EXISTS HECHOS_EQUIPO;
DROP TABLE IF EXISTS HECHOS_ASIGNACION;
DROP TABLE IF EXISTS DIM_DEPARTAMENTO;
DROP TABLE IF EXISTS DIM_HABILIDAD;
DROP TABLE IF EXISTS DIM_EQUIPO;
DROP TABLE IF EXISTS DIM_CALIDAD_FECHA;
DROP TABLE IF EXISTS DIM_ESTADO_ASIGNACION;
DROP TABLE IF EXISTS DIM_FECHA;
DROP TABLE IF EXISTS DIM_ROL;
DROP TABLE IF EXISTS DIM_PROYECTO;
DROP TABLE IF EXISTS DIM_COLABORADOR;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE DIM_COLABORADOR (
  `id_colaborador` VARCHAR(255),
  `nombre_colaborador` VARCHAR(255),
  `estatus_origen` VARCHAR(255),
  `estatus_corte` VARCHAR(255),
  `es_activo` INT,
  `baja_programada` INT,
  `fecha_incorporacion` DATE,
  `fecha_baja` DATE,
  `baja_sin_fecha` INT,
  `fecha_incorporacion_faltante` INT,
  `antiguedad_anios` DOUBLE,
  `anio_mes_baja` VARCHAR(255),
  `ubicacion` VARCHAR(255),
  `estado` VARCHAR(255),
  `pais` VARCHAR(255),
  `puesto` VARCHAR(255),
  `puesto_fuente` VARCHAR(255),
  `puesto_faltante` INT,
  `nivel_puesto` VARCHAR(255),
  `familia_puesto` VARCHAR(255),
  `departamento` VARCHAR(255),
  `departamento_codigo` VARCHAR(255),
  `departamento_fuente` VARCHAR(255),
  `tipo_nomina_original` VARCHAR(255),
  `esquema_nomina` VARCHAR(255),
  `sueldo_neto_imss` DOUBLE,
  `sueldo_asimilados_sindicato` DOUBLE,
  `sueldo_complementos` DOUBLE,
  `sueldo_neto_total` DOUBLE,
  `comision_nomina` DOUBLE,
  `impuestos_imss` DOUBLE,
  `sueldo_total_integrado` DOUBLE,
  `sueldo_faltante` INT,
  `costo_mensual` DOUBLE,
  `costo_hora` DOUBLE,
  `sgmm_aseguradora` VARCHAR(255),
  `sgmm_estatus` VARCHAR(255),
  `seguro_vida` VARCHAR(255),
  `contrato_estatus` VARCHAR(255),
  `doc_acta` VARCHAR(255),
  `doc_ine` VARCHAR(255),
  `doc_curp` VARCHAR(255),
  `doc_const_fiscal` VARCHAR(255),
  `doc_nss` VARCHAR(255),
  `doc_comprobante_domicilio` VARCHAR(255),
  `doc_banco` VARCHAR(255),
  `doc_foto` VARCHAR(255),
  `formato_rh` VARCHAR(255),
  `docs_basicos_ok` INT,
  `docs_basicos_pendientes` INT,
  `expediente_completo` INT,
  `n_asignaciones` INT,
  `tiene_asignacion` INT,
  `asignacion_vigente` INT,
  `en_banca` INT,
  `en_banca_ajustada` INT,
  `tipo_banca` VARCHAR(255),
  `costo_mensual_banca` DOUBLE,
  `costo_mensual_asignado_total` DOUBLE,
  `n_equipos` INT,
  `tiene_equipo` INT,
  `en_matriz` INT,
  `n_habs_evaluadas` INT,
  `nivel_prom_habs` DOUBLE,
  `n_habs_nivel3plus` INT,
  `matriz_confiable` INT,
  `top_habilidades` VARCHAR(255),
  PRIMARY KEY (`id_colaborador`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_PROYECTO (
  `id_proyecto` VARCHAR(255),
  `cod_cliente` VARCHAR(255),
  `cliente` VARCHAR(255),
  `industria` VARCHAR(255),
  `proyecto` VARCHAR(255),
  `estatus_proyecto` VARCHAR(255),
  `fecha_inicio` DATE,
  `fecha_fin` DATE,
  `sin_fecha_inicio` INT,
  `sin_fecha_fin` INT,
  `pm_otc` VARCHAR(255),
  `pm_sin_asignar` INT,
  `proyecto_comodin` INT,
  `estatus_inconsistente` INT,
  PRIMARY KEY (`id_proyecto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_ROL (
  `id_rol` INT,
  `rol_interno` VARCHAR(255),
  `rol_asignado` VARCHAR(255),
  `rol_efectivo` VARCHAR(255),
  `fuente_rol` VARCHAR(255),
  `rol_faltante` VARCHAR(255),
  PRIMARY KEY (`id_rol`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_FECHA (
  `id_fecha` INT,
  `fecha` DATE,
  `anio` INT,
  `trimestre` INT,
  `mes` INT,
  `nombre_mes` VARCHAR(255),
  `dia` INT,
  PRIMARY KEY (`id_fecha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_ESTADO_ASIGNACION (
  `id_estado_asignacion` INT,
  `tipo_asignacion` VARCHAR(255),
  `estatus_asignacion` VARCHAR(255),
  `estado_vigencia` VARCHAR(255),
  `persona_libre_al_vencer` VARCHAR(255),
  PRIMARY KEY (`id_estado_asignacion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_CALIDAD_FECHA (
  `id_calidad_fecha` INT,
  `fuente_fecha_inicio` VARCHAR(255),
  `fuente_fecha_fin` VARCHAR(255),
  `fecha_inicio_desconocida` VARCHAR(255),
  `fin_indefinido` VARCHAR(255),
  `ajustada_r08` VARCHAR(255),
  PRIMARY KEY (`id_calidad_fecha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_EQUIPO (
  `cod_activo` VARCHAR(255),
  `descripcion` VARCHAR(255),
  `tipo` VARCHAR(255),
  `marca` VARCHAR(255),
  `modelo` VARCHAR(255),
  `serie` VARCHAR(255),
  `modelo_faltante` INT,
  `serie_faltante` INT,
  `costo_desconocido` INT,
  `sin_responsable` INT,
  `estatus_responsable` VARCHAR(255),
  `equipo_vigente` INT,
  `situacion_equipo` VARCHAR(255),
  `equipo_a_nombre_de_baja` INT,
  `equipo_por_recuperar` INT,
  `inicio_desconocido` INT,
  `anomalia_fecha_inicio_asignacion` INT,
  PRIMARY KEY (`cod_activo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_HABILIDAD (
  `codigo_habilidad` VARCHAR(255),
  `habilidad` VARCHAR(255),
  `tecnologia` VARCHAR(255),
  `tipo_habilidad` VARCHAR(255),
  PRIMARY KEY (`codigo_habilidad`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE DIM_DEPARTAMENTO (
  `codigo_departamento` VARCHAR(255),
  `departamento` VARCHAR(255),
  `objetivo` VARCHAR(255),
  `estatus` VARCHAR(255),
  PRIMARY KEY (`codigo_departamento`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE HECHOS_ASIGNACION (
  `id_asignacion` VARCHAR(255),
  `id_colaborador` VARCHAR(255),
  `id_proyecto` VARCHAR(255),
  `id_rol` INT,
  `id_estado_asignacion` INT,
  `id_calidad_fecha` INT,
  `id_fecha_inicio_efectiva` INT,
  `id_fecha_fin_efectiva` INT,
  `id_fecha_inicio_registrada` INT,
  `id_fecha_fin_registrada` INT,
  `costo_mensual_asignado` DOUBLE,
  `pct_dedicacion` DOUBLE,
  `duracion_dias` DOUBLE,
  `dias_para_fin` DOUBLE,
  `n_asignaciones_persona` INT,
  `costo_mensual_persona` DOUBLE,
  `costo_hora_persona` DOUBLE,
  PRIMARY KEY (`id_asignacion`),
  KEY `ix_hechos_asignacion_id_colaborador` (`id_colaborador`),
  KEY `ix_hechos_asignacion_id_proyecto` (`id_proyecto`),
  KEY `ix_hechos_asignacion_id_rol` (`id_rol`),
  KEY `ix_hechos_asignacion_id_estado_asignacion` (`id_estado_asignacion`),
  KEY `ix_hechos_asignacion_id_calidad_fecha` (`id_calidad_fecha`),
  KEY `ix_hechos_asignacion_id_fecha_inicio_efectiva` (`id_fecha_inicio_efectiva`),
  KEY `ix_hechos_asignacion_id_fecha_fin_efectiva` (`id_fecha_fin_efectiva`),
  KEY `ix_hechos_asignacion_id_fecha_inicio_registrada` (`id_fecha_inicio_registrada`),
  KEY `ix_hechos_asignacion_id_fecha_fin_registrada` (`id_fecha_fin_registrada`),
  CONSTRAINT `fk_hechos_asignacion_id_colaborador` FOREIGN KEY (`id_colaborador`) REFERENCES DIM_COLABORADOR (`id_colaborador`),
  CONSTRAINT `fk_hechos_asignacion_id_proyecto` FOREIGN KEY (`id_proyecto`) REFERENCES DIM_PROYECTO (`id_proyecto`),
  CONSTRAINT `fk_hechos_asignacion_id_rol` FOREIGN KEY (`id_rol`) REFERENCES DIM_ROL (`id_rol`),
  CONSTRAINT `fk_hechos_asignacion_id_estado_asignacion` FOREIGN KEY (`id_estado_asignacion`) REFERENCES DIM_ESTADO_ASIGNACION (`id_estado_asignacion`),
  CONSTRAINT `fk_hechos_asignacion_id_calidad_fecha` FOREIGN KEY (`id_calidad_fecha`) REFERENCES DIM_CALIDAD_FECHA (`id_calidad_fecha`),
  CONSTRAINT `fk_hechos_asignacion_id_fecha_inicio_efectiva` FOREIGN KEY (`id_fecha_inicio_efectiva`) REFERENCES DIM_FECHA (`id_fecha`),
  CONSTRAINT `fk_hechos_asignacion_id_fecha_fin_efectiva` FOREIGN KEY (`id_fecha_fin_efectiva`) REFERENCES DIM_FECHA (`id_fecha`),
  CONSTRAINT `fk_hechos_asignacion_id_fecha_inicio_registrada` FOREIGN KEY (`id_fecha_inicio_registrada`) REFERENCES DIM_FECHA (`id_fecha`),
  CONSTRAINT `fk_hechos_asignacion_id_fecha_fin_registrada` FOREIGN KEY (`id_fecha_fin_registrada`) REFERENCES DIM_FECHA (`id_fecha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE HECHOS_EQUIPO (
  `cod_activo` VARCHAR(255),
  `id_colaborador` VARCHAR(255),
  `id_fecha_inicio_asignacion` INT,
  `id_fecha_fin_asignacion` INT,
  `costo_equipo` DOUBLE,
  `valor_por_recuperar` DOUBLE,
  PRIMARY KEY (`cod_activo`),
  KEY `ix_hechos_equipo_cod_activo` (`cod_activo`),
  KEY `ix_hechos_equipo_id_colaborador` (`id_colaborador`),
  KEY `ix_hechos_equipo_id_fecha_inicio_asignacion` (`id_fecha_inicio_asignacion`),
  KEY `ix_hechos_equipo_id_fecha_fin_asignacion` (`id_fecha_fin_asignacion`),
  CONSTRAINT `fk_hechos_equipo_cod_activo` FOREIGN KEY (`cod_activo`) REFERENCES DIM_EQUIPO (`cod_activo`),
  CONSTRAINT `fk_hechos_equipo_id_colaborador` FOREIGN KEY (`id_colaborador`) REFERENCES DIM_COLABORADOR (`id_colaborador`),
  CONSTRAINT `fk_hechos_equipo_id_fecha_inicio_asignacion` FOREIGN KEY (`id_fecha_inicio_asignacion`) REFERENCES DIM_FECHA (`id_fecha`),
  CONSTRAINT `fk_hechos_equipo_id_fecha_fin_asignacion` FOREIGN KEY (`id_fecha_fin_asignacion`) REFERENCES DIM_FECHA (`id_fecha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE HECHOS_HABILIDAD (
  `id_colaborador` VARCHAR(255),
  `codigo_habilidad` VARCHAR(255),
  `nivel` VARCHAR(255),
  `nivel_num` INT,
  `nivel_3_mas` INT,
  PRIMARY KEY (`id_colaborador`, `codigo_habilidad`),
  KEY `ix_hechos_habilidad_id_colaborador` (`id_colaborador`),
  KEY `ix_hechos_habilidad_codigo_habilidad` (`codigo_habilidad`),
  CONSTRAINT `fk_hechos_habilidad_id_colaborador` FOREIGN KEY (`id_colaborador`) REFERENCES DIM_COLABORADOR (`id_colaborador`),
  CONSTRAINT `fk_hechos_habilidad_codigo_habilidad` FOREIGN KEY (`codigo_habilidad`) REFERENCES DIM_HABILIDAD (`codigo_habilidad`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE PARAMETROS (
  `clave` VARCHAR(255),
  `valor` VARCHAR(255),
  PRIMARY KEY (`clave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

